css:
:root{
  --blue:#0088C0; --teal:#00A890; --grey:#888888; --deep:#0A3A52;
  --tint-blue:#eef6fb; --tint-teal:#e8f7f2; --line:#d9e2e8;
  --ink:#13303f; --ink-soft:#40515b; --white:#ffffff;
  --grad:linear-gradient(120deg,var(--blue) 0%,var(--teal) 100%);
  --grad-deep:linear-gradient(120deg,#0A3A52 0%,#0e5f74 100%);
  --shadow:0 10px 30px rgba(10,58,82,.10); --shadow-sm:0 4px 14px rgba(10,58,82,.08);
  --r:14px; --r-sm:10px; --wrap:1160px;
  --sans:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,"Noto Sans",sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--sans);color:var(--ink);background:var(--white);
  line-height:1.62;font-size:17px;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{line-height:1.18;color:var(--deep);font-weight:800;margin:0 0 .5em}
h1{font-size:clamp(2rem,4.6vw,3.05rem);letter-spacing:-.5px}
h2{font-size:clamp(1.55rem,3.1vw,2.15rem);letter-spacing:-.3px}
h3{font-size:1.22rem}
p{margin:0 0 1rem}
a{color:var(--blue);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;display:block}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.band{padding:76px 0}
.band-tint{background:var(--tint-blue)}
.band-tint-teal{background:var(--tint-teal)}
.band-deep{background:var(--grad-deep);color:#eaf4f8}
.band-deep h2,.band-deep h3{color:#fff}
.band-grad{background:var(--grad);color:#fff}
.band-grad h2{color:#fff}
.eyebrow{display:inline-block;font-weight:800;letter-spacing:1.4px;text-transform:uppercase;
  font-size:.72rem;color:var(--blue);background:var(--tint-blue);padding:6px 13px;border-radius:999px;margin-bottom:14px}
.band-deep .eyebrow,.band-grad .eyebrow{color:#fff;background:rgba(255,255,255,.16)}
.lead{font-size:1.14rem;color:var(--ink-soft);max-width:64ch}
.band-deep .lead,.band-grad .lead{color:#eaf4f8}
.center{text-align:center}
.center .lead{margin-left:auto;margin-right:auto}
/* Skip link */
.skip{position:absolute;left:-999px;top:0;background:var(--deep);color:#fff;padding:10px 16px;z-index:200;border-radius:0 0 8px 0}
.skip:focus{left:0}
/* Utility bar */
.util{background:var(--deep);color:#dbeaf1;font-size:.86rem}
.util .wrap{display:flex;flex-wrap:wrap;gap:6px 22px;align-items:center;justify-content:space-between;padding-top:8px;padding-bottom:8px}
.util a{color:#fff;font-weight:600}
.util .u-item{display:inline-flex;align-items:center;gap:7px}
.util .u-left{display:inline-flex;align-items:center;gap:8px;font-weight:600}
.util .u-right{display:inline-flex;flex-wrap:wrap;align-items:center;gap:6px 18px}
.util i{color:var(--teal)}
.util .u-sep{opacity:.35}
/* Header */
header.site{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.96);
  backdrop-filter:saturate(140%) blur(6px);border-bottom:1px solid var(--line)}
.nav{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:12px 0}
.brand{display:flex;align-items:center;gap:12px}
.brand img{height:58px;width:auto;max-width:230px;object-fit:contain}
.brand .fallback{font-weight:800;color:var(--deep);font-size:1.15rem;line-height:1.05}
.hdr-actions{display:flex;align-items:center;gap:16px}
.hdr-phone{display:inline-flex;align-items:center;gap:7px;font-weight:700;color:var(--deep);white-space:nowrap}
.hdr-phone i{color:var(--teal)}
.hdr-phone:hover{text-decoration:none;color:var(--blue)}
.menu{display:flex;align-items:center;gap:4px;list-style:none;margin:0;padding:0}
.menu>li{position:relative}
.menu>li>a,.menu>li>span{display:inline-flex;align-items:center;gap:6px;padding:10px 13px;border-radius:8px;
  font-weight:600;color:var(--ink);cursor:pointer}
.menu>li>a:hover,.menu>li>span:hover{background:var(--tint-blue);color:var(--deep);text-decoration:none}
.menu .drop{position:absolute;top:calc(100% + 6px);left:0;min-width:288px;background:#fff;border:1px solid var(--line);
  border-radius:12px;box-shadow:var(--shadow);padding:8px;opacity:0;visibility:hidden;transform:translateY(6px);transition:.16s}
.menu li:hover>.drop,.menu li:focus-within>.drop{opacity:1;visibility:visible;transform:none}
.menu .drop a{display:block;padding:9px 12px;border-radius:8px;color:var(--ink);font-weight:600}
.menu .drop a:hover{background:var(--tint-blue);text-decoration:none}
.menu .drop small{display:block;font-weight:500;color:var(--ink-soft);font-size:.8rem}
.hdr-cta{display:inline-flex;align-items:center;gap:8px;background:var(--deep);color:#fff;padding:11px 18px;border-radius:10px;font-weight:700}
.hdr-cta:hover{text-decoration:none;filter:brightness(1.08)}
.burger{display:none;background:none;border:1px solid var(--line);border-radius:9px;padding:9px 11px;font-size:1.15rem;color:var(--deep);cursor:pointer}
/* Buttons */
.btn{display:inline-flex;align-items:center;gap:9px;font-weight:700;padding:14px 24px;border-radius:11px;border:2px solid transparent;cursor:pointer;font-size:1rem;transition:.15s;text-align:center}
.btn i{font-size:.95em}
.btn-primary{background:var(--deep);color:#fff}
.btn-primary:hover{filter:brightness(1.1);text-decoration:none}
.btn-teal{background:var(--teal);color:#03302a}
.btn-teal:hover{filter:brightness(1.06);text-decoration:none}
.btn-ghost{background:transparent;color:var(--deep);border-color:var(--deep)}
.btn-ghost:hover{background:var(--deep);color:#fff;text-decoration:none}
.btn-white{background:#fff;color:var(--deep)}
.btn-white:hover{filter:brightness(.96);text-decoration:none}
.btn-lg{padding:16px 30px;font-size:1.06rem}
.cta-row{display:flex;flex-wrap:wrap;gap:14px;margin-top:26px}
/* Hero variants */
.hero{position:relative;overflow:hidden}
.hero .wrap{padding-top:64px;padding-bottom:64px}
.hero-split .grid2{display:grid;grid-template-columns:1.05fr .95fr;gap:44px;align-items:center}
.hero-split.rev .grid2{grid-template-columns:.95fr 1.05fr}
.hero-split.rev .h-media{order:-1}
.hero-tint{background:var(--tint-blue)}
.hero-grad{background:var(--grad);color:#fff}
.hero-grad h1,.hero-grad .lead{color:#fff}
.hero-grad .eyebrow,.hero-banner .eyebrow{color:#fff;background:rgba(255,255,255,.20)}
.hero-grad .lead,.hero-banner .lead{text-shadow:0 1px 2px rgba(6,40,55,.22)}
.hero-banner{background:var(--grad);color:#fff}
.hero-banner h1{color:#fff}
.hero-banner .lead{color:#fff}
.hero-banner .wrap{padding-top:80px;padding-bottom:80px;max-width:900px;text-align:center}
.hero-banner .cta-row{justify-content:center}
.hero-banner .chips{justify-content:center}
/* E-E-A-T chips */
.chips{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}
.chip{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.9);border:1px solid var(--line);
  padding:8px 14px;border-radius:999px;font-weight:600;font-size:.86rem;color:var(--deep);box-shadow:var(--shadow-sm)}
.chip i{color:var(--teal)}
.hero-grad .chip,.hero-banner .chip{background:rgba(255,255,255,.14);border-color:rgba(255,255,255,.28);color:#fff}
.hero-grad .chip i,.hero-banner .chip i{color:#bff0e4}
/* Image placeholder */
.ph{position:relative;background:linear-gradient(135deg,#dfeef6,#e7f6f1);border:2px dashed #9cc3d6;border-radius:var(--r);
  display:flex;align-items:center;justify-content:center;text-align:center;color:#4c6b79;min-height:280px;overflow:hidden}
.ph .ph-inner{padding:20px}
.ph i{font-size:1.7rem;color:#7aa8bd;margin-bottom:8px;display:block}
.ph b{display:block;font-size:.82rem;letter-spacing:.5px;text-transform:uppercase;color:#37596a}
.ph small{display:block;color:#5c7684;font-size:.78rem;margin-top:4px}
.ph-16x9{aspect-ratio:16/9;min-height:0}
.ph-4x3{aspect-ratio:4/3;min-height:0}
.ph-1x1{aspect-ratio:1/1;min-height:0}
/* Trust bar */
.trust{background:var(--deep);color:#eaf4f8;padding:20px 0}
.trust .wrap{display:flex;flex-wrap:wrap;gap:14px 30px;justify-content:center;align-items:center}
.trust .t{display:inline-flex;align-items:center;gap:10px;font-weight:600;font-size:.94rem}
.trust .t i{color:var(--teal);font-size:1.15rem}
/* Cards */
.grid{display:grid;gap:22px}
.g2{grid-template-columns:repeat(2,1fr)}
.g3{grid-template-columns:repeat(3,1fr)}
.g4{grid-template-columns:repeat(4,1fr)}
.card{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:26px;box-shadow:var(--shadow-sm);height:100%}
.card .ic{width:52px;height:52px;border-radius:12px;background:var(--tint-blue);color:var(--blue);
  display:flex;align-items:center;justify-content:center;font-size:1.3rem;margin-bottom:15px}
.card.teal .ic{background:var(--tint-teal);color:var(--teal)}
.card h3{margin-bottom:.4em}
.card p{color:var(--ink-soft);margin:0}
.card ul{margin:.4rem 0 0;padding-left:1.15em;color:var(--ink-soft)}
.card ul li{margin-bottom:.3rem}
.card .more{display:inline-flex;align-items:center;gap:7px;margin-top:14px;font-weight:700;color:var(--blue)}
/* Feature split */
.split{display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
.split.rev .s-media{order:-1}
.tick{list-style:none;padding:0;margin:18px 0 0}
.tick li{position:relative;padding:6px 0 6px 34px;color:var(--ink-soft)}
.tick li:before{content:"\f00c";font-family:"Font Awesome 6 Free";font-weight:900;color:var(--teal);
  position:absolute;left:0;top:7px;background:var(--tint-teal);width:22px;height:22px;border-radius:50%;
  display:flex;align-items:center;justify-content:center;font-size:.7rem}
.band-deep .tick li{color:#dbeaf1}
.band-deep .tick li:before{background:rgba(255,255,255,.14);color:#bff0e4}
.crosslist{list-style:none;padding:0;margin:18px 0 0}
.crosslist li{position:relative;padding:6px 0 6px 34px;color:var(--ink-soft)}
.crosslist li:before{content:"\f057";font-family:"Font Awesome 6 Free";font-weight:900;color:#b06a55;
  position:absolute;left:0;top:7px;font-size:1.05rem}
/* Tags */
.tags{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}
.tag{display:inline-flex;align-items:center;gap:8px;background:#fff;border:1px solid var(--line);padding:9px 15px;
  border-radius:999px;font-weight:600;color:var(--deep);font-size:.9rem;box-shadow:var(--shadow-sm)}
.tag i{color:var(--blue)}
.band-tint-teal .tag i{color:var(--teal)}
/* Steps */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;counter-reset:s}
.step{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:24px;position:relative}
.step .n{counter-increment:s;width:40px;height:40px;border-radius:11px;background:var(--grad);color:#fff;
  font-weight:800;display:flex;align-items:center;justify-content:center;margin-bottom:14px}
.step .n:before{content:counter(s)}
.step h3{font-size:1.06rem}
.step p{color:var(--ink-soft);margin:0;font-size:.96rem}
/* Matching band tiles */
.match{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:30px}
.mtile{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);border-radius:var(--r);padding:22px;text-align:center}
.mtile i{font-size:1.5rem;color:#bff0e4;margin-bottom:10px}
.mtile b{display:block;color:#fff;font-size:1.02rem;margin-bottom:4px}
.mtile span{color:#cfe4ec;font-size:.9rem}
/* Comparison table */
.tbl{width:100%;border-collapse:collapse;background:#fff;border-radius:var(--r);overflow:hidden;box-shadow:var(--shadow-sm);margin-top:8px}
.tbl th,.tbl td{padding:15px 18px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}
.tbl thead th{background:var(--deep);color:#fff;font-size:.95rem}
.tbl tbody th{font-weight:700;color:var(--deep);width:34%}
.tbl td{color:var(--ink-soft)}
.tbl tr:last-child td,.tbl tr:last-child th{border-bottom:none}
/* Pricing */
.price-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:30px;align-items:start}
.price-card{background:#fff;border:1px solid var(--line);border-left:5px solid var(--teal);border-radius:var(--r);padding:26px;box-shadow:var(--shadow-sm)}
.price-card h3{margin-bottom:.5em}
.note{background:var(--tint-blue);border-radius:var(--r);padding:22px;color:var(--ink-soft);font-size:.96rem}
.note i{color:var(--blue);margin-right:8px}
/* FAQ */
.faq{max-width:840px;margin:0 auto}
.qa{background:#fff;border:1px solid var(--line);border-radius:12px;margin-bottom:12px;overflow:hidden}
.qa button{width:100%;text-align:left;background:none;border:none;padding:18px 22px;font-size:1.04rem;font-weight:700;
  color:var(--deep);cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:16px;font-family:inherit}
.qa button i{color:var(--blue);transition:.2s;flex:none}
.qa button[aria-expanded="true"] i{transform:rotate(180deg)}
.qa .a{padding:0 22px;max-height:0;overflow:hidden;transition:max-height .25s ease}
.qa .a p{color:var(--ink-soft);padding-bottom:18px;margin:0}
/* Form */
.formcard{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:28px;box-shadow:var(--shadow)}
.band-deep .formcard,.band-grad .formcard{color:var(--ink)}
.formcard h3{margin-top:0}
.field{margin-bottom:14px}
.field label{display:block;font-weight:600;font-size:.9rem;color:var(--deep);margin-bottom:6px}
.field input,.field select,.field textarea{width:100%;padding:13px 14px;border:1px solid var(--line);border-radius:10px;
  font-size:1rem;font-family:inherit;color:var(--ink);background:#fdfefe}
.field input:focus,.field select:focus,.field textarea:focus{outline:3px solid rgba(0,136,192,.28);border-color:var(--blue)}
.field textarea{min-height:104px;resize:vertical}
.form-2{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}
.form-note{font-size:.82rem;color:var(--ink-soft);margin-top:6px}
.req{color:#c0392b}
/* Related */
.rel-card{display:flex;flex-direction:column;background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:22px;box-shadow:var(--shadow-sm)}
.rel-card .ic{width:46px;height:46px;border-radius:11px;background:var(--tint-teal);color:var(--teal);display:flex;align-items:center;justify-content:center;font-size:1.15rem;margin-bottom:12px}
.rel-card h3{font-size:1.08rem}
.rel-card p{color:var(--ink-soft);font-size:.95rem;flex:1}
.rel-card .more{font-weight:700;color:var(--blue);margin-top:10px;display:inline-flex;gap:7px;align-items:center}
/* Coverage */
.cov{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}
.cov a{background:#fff;border:1px solid var(--line);padding:9px 15px;border-radius:999px;font-weight:600;color:var(--deep);font-size:.9rem}
.cov a:hover{background:var(--tint-blue);text-decoration:none}
.cov a i{color:var(--blue);margin-right:6px}
/* Reviews scaffold */
.rev-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.rev{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:24px;box-shadow:var(--shadow-sm)}
.rev .stars{color:#f0a500;margin-bottom:10px;letter-spacing:2px}
.rev p{color:var(--ink-soft);font-style:italic}
.rev .who{display:flex;align-items:center;gap:12px;margin-top:14px}
.rev .av{width:44px;height:44px;border-radius:50%;background:var(--tint-blue);border:1px dashed #9cc3d6;display:flex;align-items:center;justify-content:center;color:#7aa8bd}
.rev .who b{color:var(--deep);display:block;font-size:.95rem}
.rev .who span{color:var(--ink-soft);font-size:.82rem}
/* Breadcrumb */
.crumb{background:var(--tint-blue);font-size:.86rem;padding:12px 0}
.crumb ol{list-style:none;display:flex;flex-wrap:wrap;gap:8px;margin:0;padding:0;color:var(--ink-soft)}
.crumb a{color:var(--blue);font-weight:600}
.crumb li:not(:last-child):after{content:"\f105";font-family:"Font Awesome 6 Free";font-weight:900;margin-left:8px;color:var(--grey)}
/* anchor offset */
.anchor{scroll-margin-top:120px}
/* Footer */
footer.site{background:#fff;border-top:1px solid var(--line);padding:60px 0 26px;color:var(--ink-soft)}
.f-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.1fr;gap:34px}
.f-grid img{height:50px;margin-bottom:14px}
.f-grid h4{color:var(--deep);font-size:1rem;margin-bottom:14px}
.f-grid ul{list-style:none;padding:0;margin:0}
.f-grid ul li{margin-bottom:9px}
.f-grid a{color:var(--ink-soft);font-weight:500}
.f-grid a:hover{color:var(--blue)}
.f-contact li{display:flex;gap:10px;align-items:flex-start;margin-bottom:11px}
.f-contact i{color:var(--teal);margin-top:4px;width:16px;text-align:center}
.socials{display:flex;gap:10px;margin-top:16px;flex-wrap:wrap}
.socials a{width:40px;height:40px;border-radius:10px;background:var(--tint-blue);color:var(--deep);display:flex;align-items:center;justify-content:center;font-size:1.02rem}
.socials a:hover{background:var(--deep);color:#fff;text-decoration:none}
.f-bottom{border-top:1px solid var(--line);margin-top:40px;padding-top:20px;display:flex;flex-wrap:wrap;gap:10px 22px;justify-content:space-between;font-size:.85rem}
.f-bottom .ndis{font-weight:700;color:var(--deep)}
/* Sticky mobile call */
.sticky-call{display:none}
/* Responsive */
@media(max-width:980px){
  .g4{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:repeat(2,1fr)}
  .match{grid-template-columns:repeat(2,1fr)}
  .rev-grid{grid-template-columns:1fr 1fr}
  .f-grid{grid-template-columns:1fr 1fr}
  .hero-split .grid2,.hero-split.rev .grid2,.split,.split.rev,.price-grid{grid-template-columns:1fr}
  .hero-split.rev .h-media,.split.rev .s-media{order:0}
  .hdr-cta,.hdr-phone{display:none}
}
@media(max-width:720px){
  .band{padding:54px 0}
  .menu{display:none;position:absolute;top:100%;left:0;right:0;background:#fff;border-bottom:1px solid var(--line);
    flex-direction:column;align-items:stretch;padding:10px;gap:2px;box-shadow:var(--shadow)}
  .menu.open{display:flex}
  .menu>li>a,.menu>li>span{padding:13px}
  .menu .drop{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:none;
    background:var(--tint-blue);margin:2px 0 6px;display:none}
  .menu li.open>.drop{display:block}
  .burger{display:inline-flex}
  .g2,.g3,.g4,.rev-grid,.f-grid,.steps,.match{grid-template-columns:1fr}
  .form-2{grid-template-columns:1fr}
  .util .wrap{justify-content:center}
  .sticky-call{display:flex;position:fixed;bottom:0;left:0;right:0;z-index:90;background:var(--deep);
    padding:9px;gap:9px;box-shadow:0 -6px 18px rgba(0,0,0,.18)}
  .sticky-call a{flex:1;justify-content:center;padding:12px;border-radius:10px;font-weight:700;display:inline-flex;align-items:center;gap:8px}
  body{padding-bottom:66px}
}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
